function fingerprint(documents: Record<string, LegalDocument>) {
  return createHash('sha256').update(JSON.stringify(documents), 'utf8').digest('hex')
}

export function localizeLegalDocument(slug: string, document: LegalDocument, allDocuments: Record<string, LegalDocument>, locale: 'tr' | 'en' | 'ar') {
  if (locale === 'tr') return { document, complete: true, sourceVersion: LEGAL_TRANSLATION_SOURCE_VERSION }
  if (fingerprint(allDocuments) !== LEGAL_TRANSLATION_SOURCE_FINGERPRINT) return { document, complete: false, sourceVersion: LEGAL_TRANSLATION_SOURCE_VERSION }
  const orderedParagraphs: string[] = []
  const paragraphIndex = new Map<string, number>()
  const orderedTitles: string[] = []
  const titleIndex = new Map<string, number>()
  for (const source of Object.values(allDocuments)) for (const section of source.sections) {
    if (!titleIndex.has(section.title)) { titleIndex.set(section.title, orderedTitles.length); orderedTitles.push(section.title) }
    for (const paragraph of section.paragraphs) if (!paragraphIndex.has(paragraph)) { paragraphIndex.set(paragraph, orderedParagraphs.length); orderedParagraphs.push(paragraph) }
  }
  const langIndex = locale === 'en' ? 0 : 1
  if (orderedParagraphs.length !== paragraphs.en.length || paragraphs.en.length !== paragraphs.ar.length || orderedTitles.length !== sectionTitles.length) {
    return { document, complete: false, sourceVersion: LEGAL_TRANSLATION_SOURCE_VERSION }
  }
  const titles = documentTitles[slug as keyof typeof documentTitles]
  if (!titles) return { document, complete: false, sourceVersion: LEGAL_TRANSLATION_SOURCE_VERSION }
  const localized: LegalDocument = {
    title: titles[langIndex],
    sections: document.sections.map(section => {
      const index = titleIndex.get(section.title)
      if (index === undefined) throw new Error('Legal translation source title is missing')
      return {
        title: sectionTitles[index][langIndex],
        paragraphs: section.paragraphs.map(paragraph => {
          const paragraphPosition = paragraphIndex.get(paragraph)
          if (paragraphPosition === undefined) throw new Error('Legal translation source paragraph is missing')
          return paragraphs[locale][paragraphPosition]
        }),
      }
    }),
  }
  const complete = localized.sections.every(section => section.title && section.paragraphs.every(Boolean))
  return { document: localized, complete, sourceVersion: LEGAL_TRANSLATION_SOURCE_VERSION }
}

export const LEGAL_TRANSLATION_NOTICE = {
  en: 'English translation for information. The Turkish source text is the reference version.',
  ar: 'ترجمة إلى العربية للعلم. النص التركي هو النص المرجعي.',
} as const

export const LEGAL_SECTION_TITLE_SOURCE_COUNT = sectionTitles.length
